    41	/**
    42	 * When sharing a policy (workspace) only return user avatar that is user defined. Default ws avatars have separate logic.
    43	 * In any other case default to expensify logo
    44	 */
    45	
    46	function getLogoForWorkspace(report: OnyxEntry<Report>, policy?: OnyxEntry<Policy>): ImageSourcePropType | undefined {
    47	    if (!policy || !policy.id || report?.type !== 'chat') {
    48	        return expensifyLogo;
    49	    }
    50	
    51	    if (!policy.avatarURL) {
    52	        return undefined;
    53	    }
    54	
    55	    return policy.avatarURL as ImageSourcePropType;
    56	}
