    58	function ShareCodePage({report, policy, backTo}: ShareCodePageProps) {
    59	    const themeStyles = useThemeStyles();
    60	    const StyleUtils = useStyleUtils();
    61	    const {translate} = useLocalize();
    62	    const {environmentURL} = useEnvironment();
    63	    const qrCodeRef = useRef<QRShareWithDownloadHandle>(null);
    64	
    65	    const currentUserPersonalDetails = useCurrentUserPersonalDetails();
    66	
    67	    const isReport = !!report?.reportID;
    68	
    69	    const subtitle = useMemo(() => {
    70	        if (isReport) {
    71	            if (ReportUtils.isExpenseReport(report)) {
    72	                return ReportUtils.getPolicyName(report);
    73	            }
    74	            if (ReportUtils.isMoneyRequestReport(report)) {
    75	                // generate subtitle from participants
    76	                return ReportUtils.getParticipantsAccountIDsForDisplay(report, true)
    77	                    .map((accountID) => ReportUtils.getDisplayNameForParticipant(accountID))
    78	                    .join(' & ');
    79	            }
    80	
    81	            return ReportUtils.getParentNavigationSubtitle(report).workspaceName ?? ReportUtils.getChatRoomSubtitle(report);
    82	        }
    83	
    84	        return currentUserPersonalDetails.login;
    85	    }, [report, currentUserPersonalDetails, isReport]);
    86	
    87	    const title = isReport ? ReportUtils.getReportName(report) : currentUserPersonalDetails.displayName ?? '';
    88	    // We should remove this logic once https://github.com/Expensify/App/issues/19834 is done
    89	    // We shouldn't introduce platform specific code in our codebase
    90	    // This is a temporary solution while Web is not supported for the QR code download feature
    91	    const platform = getPlatform();
    92	    const isNative = platform === CONST.PLATFORM.IOS || platform === CONST.PLATFORM.ANDROID;
    93	    const urlWithTrailingSlash = Url.addTrailingForwardSlash(environmentURL);
    94	    const url = isReport
    95	        ? `${urlWithTrailingSlash}${ROUTES.REPORT_WITH_ID.getRoute(report.reportID)}`
    96	        : `${urlWithTrailingSlash}${ROUTES.PROFILE.getRoute(currentUserPersonalDetails.accountID ?? '-1')}`;
    97	
    98	    const logo = isReport ? getLogoForWorkspace(report, policy) : (UserUtils.getAvatarUrl(currentUserPersonalDetails?.avatar, currentUserPersonalDetails?.accountID) as ImageSourcePropType);
    99	
   100	    // Default logos (avatars) are SVG and they require some special logic to display correctly
   101	    let svgLogo: React.FC<SvgProps> | undefined;
   102	    let logoBackgroundColor: string | undefined;
   103	    let svgLogoFillColor: string | undefined;
   104	
   105	    if (!logo && policy && !policy.avatarURL) {
   106	        svgLogo = ReportUtils.getDefaultWorkspaceAvatar(policy.name) || Expensicons.FallbackAvatar;
   107	
   108	        const defaultWorkspaceAvatarColors = StyleUtils.getDefaultWorkspaceAvatarColor(policy.id ?? '');
   109	        logoBackgroundColor = defaultWorkspaceAvatarColors.backgroundColor?.toString();
   110	        svgLogoFillColor = defaultWorkspaceAvatarColors.fill;
   111	    }
   112	
   113	    return (
   114	        <ScreenWrapper testID={ShareCodePage.displayName}>
   115	            <HeaderWithBackButton
   116	                title={translate('common.shareCode')}
   117	                onBackButtonPress={() => Navigation.goBack(isReport ? ROUTES.REPORT_WITH_ID_DETAILS.getRoute(report?.reportID, backTo) : undefined)}
   118	                shouldShowBackButton
   119	            />
   120	            <ScrollView style={[themeStyles.flex1, themeStyles.pt3]}>
   121	                <View style={[themeStyles.workspaceSectionMobile, themeStyles.ph5]}>
   122	                    <QRShareWithDownload
   123	                        ref={qrCodeRef}
   124	                        url={url}
   125	                        title={title}
   126	                        subtitle={subtitle}
   127	                        logo={isReport ? expensifyLogo : (UserUtils.getAvatarUrl(currentUserPersonalDetails?.avatar, currentUserPersonalDetails?.accountID) as ImageSourcePropType)}
   128	                        logoRatio={isReport ? CONST.QR.EXPENSIFY_LOGO_SIZE_RATIO : CONST.QR.DEFAULT_LOGO_SIZE_RATIO}
   129	                        logoMarginRatio={isReport ? CONST.QR.EXPENSIFY_LOGO_MARGIN_RATIO : CONST.QR.DEFAULT_LOGO_MARGIN_RATIO}
   130	                        svgLogo={svgLogo}
   131	                        svgLogoFillColor={svgLogoFillColor}
   132	                        logoBackgroundColor={logoBackgroundColor}
   133	                    />
   134	                </View>
   135	
   136	                <View style={themeStyles.mt9}>
   137	                    <ContextMenuItem
   138	                        isAnonymousAction
   139	                        text={translate('qrCodes.copy')}
   140	                        icon={Expensicons.Copy}
   141	                        successIcon={Expensicons.Checkmark}
   142	                        successText={translate('qrCodes.copied')}
   143	                        onPress={() => Clipboard.setString(url)}
   144	                        shouldLimitWidth={false}
   145	                    />
   146	                    {/* Remove this platform specific condition once https://github.com/Expensify/App/issues/19834 is done. 
   147	                    We shouldn't introduce platform specific code in our codebase. 
   148	                    This is a temporary solution while Web is not supported for the QR code download feature */}
   149	                    {isNative && (
   150	                        <MenuItem
   151	                            isAnonymousAction
   152	                            title={translate('common.download')}
   153	                            icon={Expensicons.Download}
   154	                            // eslint-disable-next-line @typescript-eslint/no-misused-promises
