   161	                        icon={Expensicons.Cash}
   162	                        onPress={() => Navigation.navigate(ROUTES.REFERRAL_DETAILS_MODAL.getRoute(CONST.REFERRAL_PROGRAM.CONTENT_TYPES.SHARE_CODE, Navigation.getActiveRoute()))}
   163	                        shouldShowRightIcon
   164	                    />
   165	                </View>
   166	            </ScrollView>
