   148	            onLayout={shouldUseAutoHitSlop ? onLayout : undefined}
   149	            ref={ref as ForwardedRef<View>}
   150	            disabled={fullDisabled}
   151	            onPress={!isDisabled ? singleExecution(onPressHandler) : undefined}
   152	            onLongPress={!isDisabled && onLongPress ? onLongPressHandler : undefined}
   153	            onKeyDown={!isDisabled ? onKeyDown : undefined}
   154	            onPressIn={!isDisabled ? onPressIn : undefined}
   155	            onPressOut={!isDisabled ? onPressOut : undefined}
