   157	                cursorStyle,
   158	                StyleUtils.parseStyleFromFunction(style, state),
   159	                isScreenReaderActive && StyleUtils.parseStyleFromFunction(screenReaderActiveStyle, state),
   160	                state.focused && StyleUtils.parseStyleFromFunction(focusStyle, state),
   161	                (state.hovered || isHovered) && StyleUtils.parseStyleFromFunction(hoverStyle, state),
   162	                state.pressed && StyleUtils.parseStyleFromFunction(pressStyle, state),
   163	                isDisabled && [StyleUtils.parseStyleFromFunction(disabledStyle, state), styles.noSelect],
