   171	            aria-keyshortcuts={keyboardShortcut && `${keyboardShortcut.modifiers.join('')}+${keyboardShortcut.shortcutKey}`}
   172	            // ios-only form of inputs
   173	            onMagicTap={!isDisabled ? voidOnPressHandler : undefined}
   174	            onAccessibilityTap={!isDisabled ? voidOnPressHandler : undefined}
   175	            accessible={accessible}
   176	            // eslint-disable-next-line react/jsx-props-no-spreading
   177	            {...rest}
   178	            onHoverOut={(event) => {
   179	                if (event?.type === 'pointerenter' || event?.type === 'mouseenter') {
   180	                    return;
   181	                }
   182	                setIsHovered(false);
   183	                if (rest.onHoverOut) {
   184	                    rest.onHoverOut(event);
   185	                }
   186	            }}
   187	            onHoverIn={(event) => {
   188	                setIsHovered(true);
   189	                if (rest.onHoverIn) {
   190	                    rest.onHoverIn(event);
   191	                }
   192	            }}
   193	        >
   194	            {(state) => (typeof children === 'function' ? children({...state, isScreenReaderActive, hovered: state.hovered || isHovered, isDisabled}) : children)}
